<?php namespace Tests\Feature;use Tests\TestCase;use App\Models\User;use App\Features\Stock\Models\Stock;use Illuminate\Foundation\Testing\RefreshDatabase;class StockBasicTest extends TestCase{use RefreshDatabase;public function test_guest_redirected_to_login():void{$this->get('/')->assertRedirect('/login');}public function test_register_page_loads():void{$this->get('/register')->assertOk();}public function test_member_can_open_stock_list():void{$u=User::factory()->create();$this->actingAs($u)->get('/stocks')->assertOk();}public function test_admin_can_open_user_list():void{$u=User::factory()->create(['role'=>'admin']);$this->actingAs($u)->get('/admin/users')->assertOk();}public function test_stock_adjustment_syncs_status():void{$u=User::factory()->create();$s=Stock::factory()->create(['user_id'=>$u->id,'quantity'=>1,'min_stock'=>3]);$s->adjust(-1);$this->assertSame('out_of_stock',$s->fresh()->status);}}